/**  One setting, named so that it can be reset without saying its value. */
export type SettingKey = "generalOnStartup" | "generalCheckForUpdates" | "generalRegionalFormat" | "appearanceTheme" | "appearanceZoom" | "appearanceFollowTextSize" | "appearanceCodeFontSize" | "appearanceCodeLigatures" | "appearanceReduceMotion" | "appearanceSmoothScrolling" | "appearanceShowStatusBar" | "layoutSidebarWidth" | "layoutInspectorWidth" | "notificationsDesktop" | "advancedLogLevel" | "advancedDeveloperMode" | "advancedNativeTitleBar" | "advancedHardwareAcceleration";

/**
 *  Every setting, as stored in `settings.json`. Keys this version does not know are ignored. The
 *  store fills in anything missing from a file with its default before reading it into this type.
 */
export type Settings = {
	/**  The version of this file's layout. Written by the app; do not change it by hand. */
	version: number,
	general: General,
	appearance: Appearance,
	layout: Layout,
	notifications: Notifications,
	keyboard: Keyboard,
	advanced: Advanced,
};

/**  Sent to the UI whenever the settings change: through the UI, or by editing the file by hand. */
export type SettingsChanged = {
	settings: Settings,
	/**  Set when the file could not be used and the defaults took over (`ARD-SET-002`). */
	notice: AppError | null,
};

/**  An action Claude Code runs when a message starts with a slash and its name. */
export type SlashCommand = {
	/**  Without the slash. A plugin's commands are named `plugin:name`. */
	name: string,
	description: string,
	/**  What follows the name, such as `<low|medium|high>`. Empty when it takes nothing. */
	argumentHint: string,
	/**  Other names that run it. */
	aliases: string[],
	/**  Whether it is Claude Code's own, not a skill, a plugin's or an MCP server's. */
	builtin: boolean,
};

/**  A moment in a reply that is not text, shown as a line of its own. */
export type StatusKind = 
/**  The agent started working on the message. */
"started" | 
/**  The person stopped the reply. */
"stopped" | 
/**  The agent could not find the session's earlier conversation, so the reply starts a new one. */
"newConversation";

/**  What the About page shows besides the app's own version. */
export type SystemInfo = {
	/**  The Windows version, such as `Windows 11 24H2 (build 26100.1234)`. */
	windows: string,
	/**  The version of the web engine (`WebView2`) that draws the window. */
	webview: string,
};

/**  What Windows says about the text size and the regional format. */
export type SystemPreferences = {
	/**  The text size as a percentage: 100 is normal, and Windows goes up to 225. */
	textScalePercent: number,
	/**  The regional format as a language tag such as `el-GR`. */
	locale: string,
};

/**  Sent to the UI whenever the text size or the regional format changes in Windows. */
export type SystemPreferencesChanged = {
	preferences: SystemPreferences,
};

/**  Which color scheme the window uses. */
export type Theme = 
/**  Follow the Windows light or dark setting. */
"system" | "light" | "dark";

/**  How a tool call ended. */
export type ToolStatus = 
/**  The agent is still using the tool. */
"running" | "done" | "failed" | 
/**  The person stopped the reply while the tool was running. */
"stopped";

/**  The person's message and the agent's reply to it. */
export type Turn = {
	id: string,
	/**  What the person wrote. */
	prompt: string,
	/**  When the message was sent, in UTC, as `2026-09-30T14:05:09Z`. */
	startedAt: string,
	status: TurnStatus,
	items: Item[],
};

/**
 *  What happens while a reply streams. The store applies these, and the UI receives them through a
 *  channel.
 */
export type TurnEvent = 
/**  A new part of the reply, with whatever it holds so far. */
{ type: "itemAdded"; turnId: string; item: Item } | 
/**  More text for a text or thinking item. The first delta of an unknown item creates a text item. */
{ type: "textDelta"; turnId: string; itemId: string; text: string } | 
/**  A tool call ended, with what the tool answered. */
{ type: "toolCallEnded"; turnId: string; itemId: string; status: ToolStatus; output: string | null } | 
/**  The reply is complete. */
{ type: "finished"; turnId: string } | 
/**  The reply stopped because something went wrong. */
{ type: "failed"; turnId: string } | 
/**  The person stopped the reply. */
{ type: "stopped"; turnId: string };

/**  How far a turn has come. */
export type TurnStatus = 
/**  The agent is still replying. */
"running" | "done" | 
/**  The reply stopped because something went wrong. */
"failed" | 
/**  The person stopped the reply. */
"stopped";

/**  How serious a message from the UI is. */
export type UiLogLevel = "error" | "warn" | "info" | "debug";

/**  Where an update is in its way to being installed. */
export type UpdateStatus = 
/**  Nothing is happening, and there is nothing to install. */
{ state: "idle" } | 
/**  Looking for a new version. */
{ state: "checking" } | 
/**  A new version is being downloaded. */
{ state: "downloading"; version: string } | 
/**  A new version is downloaded and checked. Restarting installs it. */
{ state: "ready"; version: string };

/**  Tells the UI when the status changes. */
export type UpdateStatusChanged = {
	status: UpdateStatus,
};

/**  The person's usage limits, as the agent CLI last reported them. Kept in memory only. */
export type UsageLimits = {
	report: UsageReport,
	/**  The 5-hour limit, then the weekly limit, each when known. */
	windows: UsageWindow[],
};

/**  Tells the page that Claude Code reported new usage limits (ADR 0043). */
export type UsageLimitsChanged = {
	limits: UsageLimits,
};

/**  What the agent CLI said about the person's usage limits as a whole. */
export type UsageReport = 
/**  Not asked yet, or no answer yet. */
"unknown" | 
/**  The windows are what it reported. */
"reported" | 
/**  The sign-in has no plan limits: an API key, a cloud provider, or signed out. */
"notForThisSignIn" | 
/**  This version of the agent CLI cannot report them. */
"unsupported";

/**  What the agent CLI last said about a window, beside its percentage. */
export type UsageStatus = "allowed" | 
/**  Near the limit, as the agent CLI judges it. */
"warning" | 
/**  At the limit: replies are refused until the window resets. */
"rejected";

/**  One window of a plan's usage limits. */
export type UsageWindow = {
	kind: UsageWindowKind,
	/**  How much of the window is used, in whole percent. It can pass 100. */
	percent: number,
	/**  When the window resets, in RFC 3339, when the agent CLI said. */
	resetsAt: string | null,
	status: UsageStatus,
};

/**  Which window a usage limit covers. */
export type UsageWindowKind = 
/**  The 5-hour limit. */
"fiveHour" | 
/**  The weekly limit. */
"weekly";

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

